import net from 'node:net';
function main(): void {
  const server = net.createServer((socket: any) => { console.log('cb2', typeof server); });
  server.listen(0, '127.0.0.1', () => {
    const port = (server.address() as any).port;
    const c = net.connect(port, '127.0.0.1', () => { c.end(); setTimeout(() => server.close(), 30); });
  });
}
